function header(json, name) {
  const headers = json.payload?.headers || json.headers || [];
  if (Array.isArray(headers)) {
    const found = headers.find((item) => String(item.name || '').toLowerCase() === name);
    return found?.value || '';
  }
  return '';
}

const json = $input.first().json;
const subject = json.subject || json.Subject || header(json, 'subject') || '(no subject)';
const from = json.from || json.From || header(json, 'from') || '';
const body = json.text || json.textPlain || json.snippet || json.body || '';

return [{
  json: {
    subject,
    from,
    body,
    messageId: json.id || json.messageId || '',
    promptBody: {
      prompt: 'Subject: ' + subject + '\n\nBody:\n' + body,
    },
  },
}];

const email = $('Prepare classifier').first().json;
const verdict = $input.first().json;
const suspicious = verdict.safe === false;
const threats = Array.isArray(verdict.threats) ? verdict.threats : [];
const normalFields = ['invoice_amount', 'beneficiary_name', 'invoice_number'];
const fields = suspicious
  ? Array.from(new Set([...normalFields, ...threats]))
  : normalFields;
const reason = String(verdict.reasoning || threats.join(', ') || 'SafePrompt flagged this email.').slice(0, 500);

const steps = [
  {
    action_kind: 'data_access',
    tool_name: 'aegis.data.read',
    policy_decision: 'allow',
    resource: 'invoice',
    operation: 'read',
    fields,
    purpose: 'Read supplier invoice email',
    payload: {
      task: 'Read a supplier invoice before payout',
      source: 'email',
      sensitivity: suspicious ? 'high' : 'low',
      email_subject: email.subject,
      email_from: email.from,
      fields_accessed: fields,
    },
  },
];

if (suspicious) {
  steps.push({
    action_kind: 'anomaly_signal',
    tool_name: 'aegis.anomaly.signal',
    policy_decision: 'allow',
    purpose: 'Suspicious instruction in invoice email',
    payload: {
      type: 'prompt_injection_indicator',
      severity: 'high',
      reason,
    },
  });
}

// Paste agt_... here only if more than one agent has Workflow Bridge enabled.
const agentId = '';

const capture = {
  business_context: suspicious
    ? 'Invoice email flagged: extra sensitive fields requested'
    : 'Invoice email read',
  external_system: 'n8n',
  external_workflow_id: String($workflow.id),
  external_execution_id: String($execution.id),
  status: 'completed',
  summary: suspicious ? reason : 'Normal invoice email recorded.',
  steps,
};
if (agentId) capture.agent_id = agentId;

return [{ json: { capture, suspicious, subject: email.subject } }];
